<body>
    <div class="chat-container">
        <div class="chat-header">
            <h1>ChatGPT-like Assistant</h1>
        </div>

        <div class="chat-messages" id="chatMessages">
            <div class="message bot-message">
                <div class="message-content">
                    Hello! I'm your AI assistant. How can I help you today?
                </div>
            </div>
        </div>

        <div class="typing-indicator" id="typingIndicator">
            <span></span>
            <span></span>
            <span></span>
        </div>

        <div class="chat-input">
            <input type="text" id="userInput" placeholder="Type your message here..." autocomplete="off">
            <button id="sendButton">➤</button>
        </div>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', function () {
            const chatMessages = document.getElementById('chatMessages');
            const userInput = document.getElementById('userInput');
            const sendButton = document.getElementById('sendButton');
            const typingIndicator = document.getElementById('typingIndicator');

            // Function to add a message to the chat
            function addMessage(content, isUser = false) {
                const messageDiv = document.createElement('div');
                messageDiv.className = `message ${isUser ? 'user-message' : 'bot-message'}`;

                const messageContent = document.createElement('div');
                messageContent.className = 'message-content';
                messageContent.textContent = content;

                messageDiv.appendChild(messageContent);
                chatMessages.appendChild(messageDiv);

                // Scroll to bottom
                chatMessages.scrollTop = chatMessages.scrollHeight;
            }

            // Function to simulate bot response
            function getBotResponse(userMessage) {
                const responses = [
                    "I understand what you're saying. Could you provide more details?",
                    "That's an interesting point. How can I assist you further?",
                    "Thanks for sharing that. What else would you like to know?",
                    "I appreciate your input. Is there anything specific you'd like help with?",
                    "I see. How can I make this information more useful for you?",
                    "Good question! Let me think about that for a moment.",
                    "I'm here to help. Can you tell me more about what you're looking for?",
                    "That's a great point. What would you like to explore next?",
                    "I'm processing your request. Is there anything else you'd like to discuss?",
                    "Thanks for your message. How else can I assist you today?"
                ];

                // Simple response logic based on keywords
                const lowerMessage = userMessage.toLowerCase();

                if (lowerMessage.includes('hello') || lowerMessage.includes('hi')) {
                    return "Hello there! How can I assist you today?";
                } else if (lowerMessage.includes('help')) {
                    return "I'm happy to help! You can ask me questions, request information, or just chat. What do you need?";
                } else if (lowerMessage.includes('thank')) {
                    return "You're welcome! Is there anything else I can help you with?";
                } else if (lowerMessage.includes('name')) {
                    return "I'm your AI assistant. You can call me whatever you like!";
                } else if (lowerMessage.includes('weather')) {
                    return "I don't have real-time weather data, but I can help you find weather information if you tell me your location.";
                } else if (lowerMessage.includes('bye') || lowerMessage.includes('goodbye')) {
                    return "Goodbye! Feel free to come back if you have more questions.";
                }

                // Return random response if no keywords match
                return responses[Math.floor(Math.random() * responses.length)];
            }

            // Function to handle sending a message
            function sendMessage() {
                const message = userInput.value.trim();
                if (message === '') return;

                // Add user message
                addMessage(message, true);
                userInput.value = '';

                // Show typing indicator
                typingIndicator.style.display = 'block';
                chatMessages.scrollTop = chatMessages.scrollHeight;

                // Simulate bot thinking
                setTimeout(() => {
                    typingIndicator.style.display = 'none';
                    const botResponse = getBotResponse(message);
                    addMessage(botResponse);
                }, 1000 + Math.random() * 1000);
            }

            // Event listeners
            sendButton.addEventListener('click', sendMessage);

            userInput.addEventListener('keypress', function (e) {
                if (e.key === 'Enter') {
                    sendMessage();
                }
            });

            // Focus input field
            userInput.focus();
        });
    </script>
</body>

